
:root{--parch:#f3e7cd;--ink:#3a2d1c;--wood:#1c1610;--gold:#d4a437}

.card{position:relative;background:rgba(243,231,205,.05);border:1px solid rgba(212,164,55,.35);border-radius:14px;padding:14px 12px 12px;text-align:center;overflow:hidden}

.rank{position:absolute;top:8px;left:10px;font-size:15px;color:var(--gold);opacity:.9}

.doll{position:relative;width:150px;aspect-ratio:1;margin:0 auto}

.doll .base{position:absolute;inset:0;width:100%;height:100%;z-index:2}

.im{background-size:100% 100%;background-repeat:no-repeat}

.doll .ly .im{position:absolute;inset:0;width:100%;height:100%;transform-origin:center center}

.doll .ly{position:absolute;inset:0}


.doll .face{position:absolute;inset:0;width:100%;height:100%}

.halo{position:absolute;left:50%;top:50%;transform:translate(-50%,-50%);border-radius:50%;pointer-events:none;z-index:0}

.ring{-webkit-mask-image:radial-gradient(circle, transparent 55%, #000 62%, #000 72%, transparent 80%);mask-image:radial-gradient(circle, transparent 55%, #000 62%, #000 72%, transparent 80%)}

.ground{position:absolute;left:50%;bottom:2%;width:78%;height:16%;transform:translateX(-50%);border-radius:50%;border:2px solid;pointer-events:none;z-index:0;animation:breathe 2.6s ease-in-out infinite}

@keyframes spin{to{transform:translate(-50%,-50%) rotate(360deg)}}

@keyframes breathe{0%,100%{opacity:.8}50%{opacity:1}}

.sname{font-size:18px;font-weight:700;color:#f7edd4;margin-top:8px}

.lv{margin-top:4px;font-size:14px;color:var(--gold)}

.lv .title{margin-left:8px;color:#e5c56b;background:rgba(212,164,55,.14);border-radius:6px;padding:1px 8px;font-size:13px}

.exp{margin-top:4px;font-size:13px;color:#cbbb92}

.eq{list-style:none;margin-top:10px;text-align:left;font-size:13px;border-top:1px dashed rgba(212,164,55,.3);padding-top:8px}

.eq li{display:flex;align-items:baseline;gap:6px;padding:2px 0}

.eq .slot{flex:0 0 40px;color:#9d8c66;font-size:12px}

.eq .iname{font-weight:600}

.eq .ien{margin-left:auto;color:#8a7a58;font-size:11px}

.eq .none{color:#8a7a58}

